CREATE TABLE v207569 (v207570 INT AUTO_INCREMENT, v207571 INT NOT NULL, v207572 INT NOT NULL, v207573 DATE NOT NULL, v207574 DATE NOT NULL, v207575 TIME NOT NULL, v207576 TIME NOT NULL, v207577 DATETIME NOT NULL, v207578 DATETIME NOT NULL, v207579 VARCHAR(1) NOT NULL, v207580 VARCHAR(1) NOT NULL, PRIMARY KEY (v207580), INDEX(v207576), INDEX(v207570), INDEX(v207574), INDEX(v207571), INDEX(v207579, v207578)) AS SELECT FIELD('b' COLLATE latin1_bin, 'A', 'B'), ST_INTERSECTS(ST_GEOMFROMTEXT('POLYGON((0 0,20 10,10 30, 0 0))'), ST_GEOMFROMTEXT('POLYGON((10 10,30 20,20 40, 10 10))')), FIELD('B', 'A', 'B'), ST_ASTEXT(ST_CONVEXHULL(ST_GEOMFROMTEXT('multipoint(0 0, 1 1, 2 2)'))), VALIDATE_PASSWORD_STRENGTH(), CRC32(UPPER('goodyear')), VERSION_TOKENS_DELETE('x', 123)